export const SKIP_REASONS=Object.freeze(["no-time","no-access","already-clean","customer-asked"]),WORDS_MAX=120;export function emptyProgress(){return{marks:{}}}export function cleanMark(e){if(!e||typeof e!="object")return null;if(e.status==="done")return{status:"done"};if(e.status!=="skipped")return null;const s=SKIP_REASONS.includes(e.reason)?e.reason:null,n=String(e.words||"").replace(/\s+/g," ").trim().slice(0,WORDS_MAX);return!s&&!n?null:{status:"skipped",reason:s,words:n}}export function cleanProgress(e){const s=emptyProgress(),n=e&&typeof e=="object"&&e.marks&&typeof e.marks=="object"?e.marks:{};for(const[o,t]of Object.entries(n)){const c=cleanMark(t);c&&(s.marks[o]=c)}return s}export function applyMark(e,s,n){const o={...e&&e.marks||{}};if(n===null)return delete o[s],{marks:o};const t=cleanMark(n);return t?(o[s]=t,{marks:o}):e||emptyProgress()}export function summarize(e,s){const n=s&&s.marks||{},o=e&&e.items||[],t={total:o.length,done:0,skipped:0,toGo:0,starred:0,starredDone:0,starredSkipped:0,starredToGo:0};for(const c of o){const r=n[c.id];r&&r.status==="done"?t.done++:r&&r.status==="skipped"?t.skipped++:t.toGo++,c.important&&(t.starred++,r?r.status==="done"?t.starredDone++:t.starredSkipped++:t.starredToGo++)}return t}
